import {stations,kinds,priceFor,filterPriceFor,bestOffer,filterProperties,safeUrl,compareSet} from './model-b475bb3e3a67.mjs';
const app=document.querySelector('#app');let data;let sourceData={sources:[]};let sourceStation="ลุมพินี";let toastTimer;const num=n=>Number(n).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'});const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dt=v=>v?new Date(v).toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Bangkok'}):'ไม่ระบุ';
function saved(key){try{return JSON.parse(localStorage.getItem(key)||'[]');}catch{return [];}}
let favorites=saved('nearone-favorites'),compare=saved('nearone-compare');let facebookState={budget:10000,sort:'asc'};let state={budget:10000,query:'',tab:'all',station:'',sort:'recommended',term:'all',kinds:[],privateOnly:false,onlyKnown:false,walk:'all'};
function persist(){try{localStorage.setItem('nearone-favorites',JSON.stringify(favorites));localStorage.setItem('nearone-compare',JSON.stringify(compare));}catch{}counts();}
function counts(){document.querySelector('#fav-count').textContent=favorites.length;document.querySelector('#compare-count').textContent=compare.length;}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2300);}
const get=id=>data.properties.find(p=>p.id===id);
const photo=(p,i=0)=>safeUrl(new URL(p.photos?.[i]?.url||p.photos?.[0]?.url||'assets/room-placeholder.svg',location.href).href);
const img=(p,i=0,cls='')=>`<img src="${esc(photo(p,i))}" class="${cls}" alt="${esc(p.name)}${p.photos?.length?' · รูปจาก '+esc(p.sourceName):' · ยังไม่มีรูปจากประกาศ'}" loading="lazy" data-fallback>`;
function status(p){if(p.needsReview)return ['ต้องตรวจข้อมูลใหม่','amber'];if(p.availability==='full')return ['ประกาศระบุเต็ม','gray'];if(p.category==='excluded')return ['แยกออก · ไม่ผ่านเกณฑ์','gray'];if(p.category==='alternative')return [p.kind==='capsule'?'ทางเลือก · แคปซูล':'ทางเลือก · ห้องน้ำรวม','gray'];if(p.category==='six')return ['สัญญา 6 เดือน',''];if(p.availability==='future')return ['ว่าง '+dt(p.availableFrom),''];if(p.category==='lead')return ['เบาะแส · ต้องยืนยัน','amber'];return ['เช่าสั้นได้ตามประกาศ',''];}
function pricing(p,term='all'){const o=bestOffer(p,term);return o?`฿${num(o.price)}<small> / เดือน</small><span class="price-sub">${o.unconfirmed?'ราคาเดิม ต้องยืนยัน · ':''}สัญญา ${o.months} เดือน${o.servicePercent?' + บริการ '+o.servicePercent+'%':''}</span>`:`<span style="font-size:18px">สอบถามราคาเช่าสั้น</span><span class="price-sub">${p.indicativePrice?'ราคาอ้างอิง ฿'+num(p.indicativePrice)+' · ยังใช้เป็นราคาเช่าสั้นไม่ได้':'ยังไม่มีราคาแยกตามสัญญา'}</span>`;}
function card(p,forcedTerm){const [label,color]=status(p);const term=typeof forcedTerm==='string'?forcedTerm:['short','six'].includes(state.tab)?state.tab:state.term;return `<article class="card"><a href="#/stay/${esc(p.id)}" class="card-photo">${img(p)}<span class="badge ${color}">${esc(label)}</span><span class="photo-credit">${p.photos?.length?'รูปจาก '+esc(p.sourceName):'ยังไม่มีรูปประกาศ'}</span></a><button class="heart ${favorites.includes(p.id)?'selected':''}" data-fav="${p.id}" aria-label="${favorites.includes(p.id)?'ลบ':'บันทึก'} ${esc(p.name)}" aria-pressed="${favorites.includes(p.id)}">${favorites.includes(p.id)?'♥':'♡'}</button><div class="card-body"><div class="card-type">${esc(kinds[p.kind])} <span>·</span> ${esc(p.sourceName)}</div><h3><a href="#/stay/${p.id}">${esc(p.name)}</a></h3><div class="station-line"><span class="mrt">M</span> ${esc(p.station)} <span>· ${p.stops===0?'สถานีเดียวกับ One Bangkok':p.stops+' สถานีถึงลุมพินี'}</span></div><div class="card-meta"><span>▧ ${p.size??"ไม่ระบุ"} ตร.ม.</span><span>◫ ${p.bathroom==='private'?'ห้องน้ำในตัว':p.bathroom==='shared'?'ห้องน้ำรวม':'ห้องน้ำต้องยืนยัน'}</span></div><p class="card-note">${p.walkingVerified?'✓ ยืนยันเดิน '+p.walkingMeters+' ม.':'◦ ระยะเดินถึง MRT ยังไม่ยืนยัน'}</p>${p.exclusionReason?`<p class="card-note">${esc(p.exclusionReason)}</p>`:""}<div class="card-bottom"><div class="price">${pricing(p,term)}</div><a class="arrow-link" href="#/stay/${p.id}" aria-label="ดูรายละเอียด ${esc(p.name)}">ดูรายละเอียด ↗</a></div><label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${compare.includes(p.id)?'checked':''}> เพิ่มเพื่อเปรียบเทียบ</label></div></article>`;}
function home(){document.title='NEAR ONE — อยู่ใกล้ ใช้ชีวิตง่าย';const hero=get('ua-amornsuk');app.innerHTML=`<div class="container"><section class="hero"><div><div class="eyebrow">A LITTLE CLOSER TO YOUR EVERYDAY</div><h1>อยู่ใกล้ที่ทำงาน<br>ให้ชีวิต <em>มีเวลามากขึ้น.</em></h1><p>รวมหอพัก อพาร์ตเมนต์ และคอนโดใกล้ One Bangkok<br>เลือกงบที่สบายใจ และสัญญาที่พอดีกับคุณ</p><div class="hero-links"><span><b>฿10,000</b> งบต่อเดือน</span><span><b>7</b> สถานี MRT</span><span><b>1–4</b> เดือนเป็นหลัก</span></div></div><a class="hero-art" href="#/stay/ua-amornsuk">${img(hero)}<div class="hero-pill">⌖ ONE BANGKOK NEIGHBORHOOD</div><div class="hero-art-label"><small>A PLACE TO CALL YOUR OWN</small><h2>เริ่มต้นวัน ในที่ของคุณ</h2><span>สำรวจตัวเลือกเช่าระยะสั้น &nbsp; ↗</span></div></a></section><form class="search-box" id="search-form"><span class="search-symbol">⌕</span><input id="search" aria-label="ค้นหาชื่อที่พัก ย่าน หรือสถานี" placeholder="ค้นหาชื่อที่พัก ย่าน หรือสถานี MRT…" value="${esc(state.query)}"><button class="search-btn" type="submit">ค้นหาที่พัก ↗</button></form><div class="station-strip"><label>เลือกสถานี</label><button class="station-chip ${!state.station?'active':''}" data-station="">ทุกสถานี</button>${stations.map(s=>`<button class="station-chip ${state.station===s?'active':''}" data-station="${s}">${s}<small>${Math.abs(stations.indexOf(s)-3)} สถานี</small></button>`).join('')}</div><section class="browse"><aside class="filters"><div class="filter-top"><strong>☷ &nbsp;ปรับให้ตรงใจ</strong><button class="link-btn" data-reset>ล้างตัวกรอง</button><button class="link-btn mobile-filter" data-expand aria-expanded="false">ตัวกรองเพิ่มเติม ▾</button></div><div class="filter-group"><label class="filter-label" for="budget">งบค่าเช่า / เดือน</label><div class="price-read">฿<span id="budget-value">${num(state.budget)}</span> <small>ไม่เกิน</small></div><input class="range" type="range" id="budget" min="2500" max="15000" step="500" value="${state.budget}" aria-label="งบค่าเช่าสูงสุด"><div class="range-limits"><span>฿2,500</span><span>฿15,000</span></div><p class="filter-note">กรองและเรียงด้วยราคาเช่าตามสัญญา หากยังไม่มี ใช้ราคาอ้างอิงของประกาศ</p><label class="check"><input type="checkbox" data-filter="onlyKnown" ${state.onlyKnown?'checked':''}> แสดงเฉพาะที่มีราคาเช่าสั้น</label></div><div class="filter-group"><label class="filter-label" for="term">ระยะสัญญา</label><select id="term"><option value="all">ทุกระยะสัญญา</option><option value="short" ${state.term==='short'?'selected':''}>1–4 เดือน</option><option value="six" ${state.term==='six'?'selected':''}>6 เดือน</option></select></div><div class="filter-group"><span class="filter-label">ประเภทที่พัก</span>${Object.entries(kinds).map(([v,t])=>`<label class="check"><input type="checkbox" data-kind="${v}" ${state.kinds.includes(v)?'checked':''}>${t}</label>`).join('')}</div><div class="filter-group"><span class="filter-label">ความสะดวก</span><label class="check"><input type="checkbox" data-filter="privateOnly" ${state.privateOnly?'checked':''}> ห้องน้ำในตัวที่มีข้อมูลชัดเจน</label><select id="walk" aria-label="ระยะเดินถึง MRT"><option value="all">รวมระยะเดินที่ยังไม่ยืนยัน</option><option value="verified500" ${state.walk==='verified500'?'selected':''}>ยืนยันระยะเดิน ≤ 500 ม.</option><option value="verified800" ${state.walk==='verified800'?'selected':''}>ยืนยันระยะเดิน ≤ 800 ม.</option></select></div><p class="filter-note">เกณฑ์หลักคือเดินถึงทางเข้า MRT ไม่เกิน 500 ม. กลุ่มสำรอง 501–800 ม. ระยะจากเว็บไม่ถือเป็นระยะเดินที่ยืนยัน</p></aside><div><div class="results-top"><div><h2>ค้นพบที่พักของคุณ <span id="result-count"></span></h2><p>เรียงตามความสะดวกจากข้อมูลที่มี · ระยะเดินจริงยังต้องตรวจเพิ่ม</p></div><select class="sort" id="sort" aria-label="เรียงที่พัก"><option value="recommended">แนะนำสำหรับคุณ</option><option value="asc" ${state.sort==='asc'?'selected':''}>ราคา: น้อย → มาก</option><option value="desc" ${state.sort==='desc'?'selected':''}>ราคา: มาก → น้อย</option><option value="stops" ${state.sort==='stops'?'selected':''}>จำนวนสถานีน้อยที่สุด</option></select></div><div class="tabs">${[['all','ตัวเลือกทั้งหมด'],['short','เช่า 1–4 เดือน'],['six','สัญญา 6 เดือน'],['lead','ต้องสอบถาม'],['alternative','แคปซูล / ห้องน้ำรวม'],['excluded','เต็ม / เกินเกณฑ์']].map(([v,t])=>`<button class="tab ${state.tab===v?'active':''}" data-tab="${v}">${t}</button>`).join('')}</div><div id="results" class="cards"></div><div class="notice">ⓘ <span>กรองและเรียงจากราคาเช่าตามสัญญา หรือราคาอ้างอิงเมื่อยังไม่มีราคาเช่าสั้น ราคาอ้างอิงยังต้องสอบถามเงื่อนไขเช่าสั้น ห้องที่ไม่มีราคาจะอยู่ท้ายการเรียง ห้องว่างและระยะเดินยังต้องยืนยัน</span></div></div></section></div>`;renderResults();}
function renderResults(){const list=filterProperties(data.properties,state);document.querySelector('#result-count').textContent=`${list.length} แห่ง`;document.querySelector('#results').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h3>ยังไม่มีที่พักตามตัวกรองนี้</h3><p>${state.walk!=='all'?'ข้อมูลที่มีอยู่ยังไม่มีระยะเดินถึงทางเข้า MRT ที่ตรวจยืนยันครบ':'ลองปรับงบ สถานี หรือระยะสัญญา แล้วค้นหาอีกครั้ง'}</p><button class="outline" data-reset>ล้างตัวกรอง</button></div>`;}
function table(rows){return `<table class="fact-table"><tbody>${rows.map(([a,b])=>`<tr><th>${esc(a)}</th><td>${esc(b??'ยังไม่ระบุ ต้องสอบถาม')}</td></tr>`).join('')}</tbody></table>`;}
function detail(p){if(!p){notFound();return;}document.title=p.name+' · NEAR ONE';const [label,color]=status(p);const fee=p.fees||{};app.innerHTML=`<div class="container"><div class="crumb"><a href="#/">ค้นหาที่พัก</a> &nbsp;/&nbsp; ${esc(p.name)}</div><div class="detail-head"><div><div class="eyebrow">${esc(kinds[p.kind])} · ${esc(p.station)}</div><h1>${esc(p.name)}</h1><p>⌖ ${esc(p.address)} · ${esc(p.subtitle)}</p></div><button class="outline" data-fav="${p.id}">${favorites.includes(p.id)?'♥ บันทึกแล้ว':'♡ บันทึกรายการนี้'}</button></div><div class="detail-gallery">${img(p)}<div class="gallery-secondary">${img(p,1)}${img(p,2)}</div></div><div class="detail-layout"><div><div class="panel"><div class="detail-facts"><div><strong>${p.size??"ไม่ระบุ"} ตร.ม.</strong><small>ขนาดที่ประกาศระบุ</small></div><div><strong>${p.floor?'ชั้น '+p.floor:'–'}</strong><small>ชั้นของห้อง</small></div><div><strong>${p.stops} สถานี</strong><small>จากลุมพินี</small></div></div><h2>พื้นที่เล็ก ๆ สำหรับวันของคุณ</h2><p>${esc(p.subtitle)}</p><div class="tag-list">${p.amenities.map(a=>`<span>${esc(a)}</span>`).join('')}<span>${p.bathroom==='private'?'ห้องน้ำในตัว':p.bathroom==='shared'?'ห้องน้ำรวม':'ห้องน้ำต้องยืนยัน'}</span></div><h3>ข้อมูลที่ควรรู้ก่อนเลือก</h3><ul>${p.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></div><section class="panel"><h2>การเดินทางไป One Bangkok</h2>${table([['สถานี MRT',p.station+' · '+p.stops+' สถานีจากลุมพินี'],['ระยะถึงทางเข้า MRT',p.walkingClaim],['สถานะระยะเดิน',p.walkingVerified?'ตรวจยืนยัน '+p.walkingMeters+' เมตร':'ยังไม่ยืนยันเส้นทางเดินจริง ทางข้าม และทางเข้าสถานี'],['ไป One Bangkok',p.oneBangkok],['ต้องต่อวินหรือรถไหม','ยังไม่ยืนยันเส้นทางเดิน จึงยังรับรองว่าเดินถึงได้โดยไม่ต่อรถไม่ได้']])}<a class="source-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+' '+p.address+' กรุงเทพมหานคร')}" target="_blank" rel="noopener noreferrer">เปิดแผนที่เพื่อดูเส้นทางด้วยตนเอง ↗</a></section><section class="panel"><h2>ค่าใช้จ่ายและเงื่อนไข</h2>${table([['ค่าแรกเข้าตามข้อมูลที่มี',fee.entry||'ยังสรุปยอดไม่ได้ ต้องยืนยันราคาเช่าสั้น ประกัน ล่วงหน้า และค่าธรรมเนียม'],['เงินประกัน',typeof fee.deposit==='number'?'฿'+num(fee.deposit):fee.deposit],['ค่าเช่าล่วงหน้า',fee.advance],['ค่าไฟ',fee.electric],['ค่าน้ำ',fee.water],['ค่าบริการอื่น',fee.service],['อินเทอร์เน็ต',fee.internet],['สถานะห้อง',p.availability==='full'?'ประกาศระบุเต็ม':p.availableFrom?'ผู้ประกาศระบุว่าง '+dt(p.availableFrom):p.availability==='advertised'?'ประกาศระบุว่าง ยังไม่ยืนยันกับเจ้าของ':'ยังไม่ยืนยันห้องว่าง']])}</section><section class="panel"><h2>ที่มาและความสดของข้อมูล</h2>${table([['แหล่งข้อมูล',p.sourceName],['ขั้นต่ำสัญญาจากคำบรรยาย',p.minLeaseMonths?p.minLeaseMonths+' เดือน; ราคาของระยะนี้ยังต้องตรวจ':'ดูตารางราคาและหมายเหตุ'],['วันที่โพสต์',p.posterDateLabel||'ต้นทางไม่ระบุแยก'],['วันที่ผู้ประกาศอัปเดต',dt(p.posterUpdated)],['ข้อมูลเงื่อนไขอ้างอิง ณ',dt(p.factsAsOf)],['ตรวจหน้าเว็บล่าสุด',p.lastFetchedAt?new Date(p.lastFetchedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}):'ยังไม่มีการตรวจอัตโนมัติ'],['ยืนยันกับเจ้าของ',p.ownerConfirmed?'ยืนยันแล้ว':'ยังไม่ได้ติดต่อเจ้าของ'],['สถานะการตรวจอัตโนมัติ',p.checkStatus==='ok'?'เข้าถึงหน้าเว็บได้ ไม่ได้ยืนยันห้องว่าง':p.checkStatus==='error'?'เข้าถึงต้นทางไม่สำเร็จ เก็บข้อมูลเดิมไว้':p.sourceMode==='manual'?'อ่านและคัดด้วยตนเอง ไม่ได้ตรวจ Facebook อัตโนมัติรายชั่วโมง':'ยังไม่ตรวจ']])}${p.additionalSources?.length?`<h3>ประกาศอื่นของที่พักเดียวกัน</h3>${p.additionalSources.map(v=>`<p><a class="source-link" href="${esc(safeUrl(v.url))}" target="_blank" rel="noopener noreferrer">${esc(v.name)} ↗</a>${v.facts?`<br>${esc(v.facts)}`:""}</p>`).join('')}`:''}<p>รูปภาพเป็นภาพจากประกาศของที่พัก อาจไม่ใช่ห้องที่ว่างในวันที่เลือกเข้าพัก</p></section></div><aside class="booking panel"><p class="eyebrow">YOUR NEXT PLACE</p><div class="price">${pricing(p)}</div><p>${esc(label)}</p><table class="lease-table"><tbody>${p.offers.length?p.offers.map(o=>`<tr class="${o.price>10000?'over':''}"><td>${o.months} เดือน${o.unconfirmed?' · ต้องยืนยัน':''}</td><td>฿${num(o.price)}${o.price>10000?' <small>เกินงบ</small>':''}</td></tr>`).join(''):'<tr><td>1–4 เดือน</td><td style="font-size:16px">สอบถามราคา</td></tr>'}</tbody></table><a class="primary" href="${esc(safeUrl(p.sourceUrl))}" target="_blank" rel="noopener noreferrer">ดูประกาศต้นทาง ↗</a><button class="outline" data-compare="${p.id}">${compare.includes(p.id)?'✓ เพิ่มในรายการเปรียบเทียบแล้ว':'+ เพิ่มเพื่อเปรียบเทียบ'}</button><p class="source-caption">เปิดไปยัง ${esc(p.sourceName)} โดยตรง<br>ยังไม่ได้ยืนยันห้องว่างหรือราคากับเจ้าของ</p>${p.needsReview?'<div class="source-warning">ต้นทางมีข้อมูลเปลี่ยน ต้องตรวจเงื่อนไขอีกครั้ง ราคาที่เก็บไว้อาจไม่ใช่ราคาปัจจุบัน</div>':''}</aside></div></div>`;}
function favoritePage(){app.innerHTML=`<div class="container section-page"><div class="eyebrow">SAVED FOR LATER</div><h1>ที่ที่คุณอยากกลับมาดู.</h1><p style="color:var(--muted)">บันทึกไว้ในเบราว์เซอร์นี้ · ${favorites.length} รายการ</p><div class="cards">${data.properties.filter(p=>favorites.includes(p.id)).map(card).join('')||'<div class="empty"><h3>ยังไม่มีรายการโปรด</h3><p>กดหัวใจบนที่พักที่สนใจเพื่อเก็บไว้ดูภายหลัง</p><a href="#/" class="primary">ค้นหาที่พัก ↗</a></div>'}</div></div>`;}
function comparePage(){const list=compare.map(get).filter(Boolean);const rows=[['ค่าเช่าตามสัญญา',p=>{const o=bestOffer(p);return o?'฿'+num(o.price)+' / '+o.months+' เดือน':'ราคาระยะสั้นยังไม่ยืนยัน';}],['สถานี / จำนวนสถานี',p=>p.station+' / '+p.stops+' สถานี'],['ระยะเดิน',p=>p.walkingClaim+' · ยังไม่ยืนยัน'],['ขนาด / ห้องน้ำ',p=>p.size+' ตร.ม. / '+(p.bathroom==='private'?'ในตัว':p.bathroom==='shared'?'รวม':'ต้องยืนยัน')],['วันว่าง',p=>p.availableFrom?dt(p.availableFrom):p.availability==='full'?'เต็ม':'ต้องยืนยัน'],['เงินประกัน',p=>p.fees.deposit==null?'ต้องสอบถาม':typeof p.fees.deposit==='number'?'฿'+num(p.fees.deposit):p.fees.deposit],['วันที่ผู้ประกาศอัปเดต',p=>dt(p.posterUpdated)]];app.innerHTML=`<div class="container section-page"><div class="eyebrow">SIDE BY SIDE</div><h1>เลือกง่ายขึ้น เมื่อเห็นด้วยกัน.</h1><p style="color:var(--muted)">เปรียบเทียบได้สูงสุด 3 ที่พัก ราคาผูกกับระยะสัญญาของแต่ละแห่ง</p>${list.length?`<div class="compare-table-wrap"><table class="compare-table"><thead><tr><th>รายละเอียด</th>${list.map(p=>`<td>${img(p)}<h3><a href="#/stay/${p.id}">${esc(p.name)} ↗</a></h3><button class="link-btn" data-compare="${p.id}">นำออก</button></td>`).join('')}</tr></thead><tbody>${rows.map(([k,fn])=>`<tr><th>${k}</th>${list.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th>ประกาศต้นทาง</th>${list.map(p=>`<td><a class="source-link" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(p.sourceUrl))}">${esc(p.sourceName)} ↗</a></td>`).join('')}</tr></tbody></table></div>`:'<div class="empty"><h3>เลือกที่พักมาเปรียบเทียบก่อน</h3><p>ทำเครื่องหมาย “เพิ่มเพื่อเปรียบเทียบ” บนการ์ดที่พัก</p><a href="#/" class="primary">ไปเลือกที่พัก ↗</a></div>'}</div>`;}
function updates(){const r=data.lastRun;const schedule=data.schedule;const active=schedule?.state==='active';app.innerHTML=`<div class="container"><div class="update-title"><div class="eyebrow">KNOW WHAT YOU ARE LOOKING AT</div><h1>ข้อมูลชัด เลือกได้สบายใจ.</h1><p style="color:var(--muted)">แยกการตรวจหน้าเว็บออกจากการยืนยันราคา ห้องว่าง และระยะเดิน</p></div><div class="status-grid"><div class="panel"><small>การอัปเดตรายชั่วโมง</small><h3>${active?'ตั้งเวลาแล้ว':'ยังไม่เปิดใช้งาน'}</h3><p>${active?'ตรวจจากประกาศสาธารณะตามเวลาที่ตั้งไว้':'มี workflow และตัวตั้งเวลาบน Mac พร้อมติดตั้ง ต้องเปิดใช้งานก่อน'}</p></div><div class="panel"><small>ตรวจต้นทางล่าสุด</small><h3>${r?new Date(r.finishedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}):'ยังไม่ตรวจอัตโนมัติ'}</h3><p>${r?`${r.success} หน้าเข้าถึงได้ · ${r.failed} หน้าตรวจไม่สำเร็จ`:'ข้อมูลเริ่มต้นจากแชทและหน้าประกาศ'}</p></div><div class="panel"><small>แค็ตตาล็อก</small><h3>${data.properties.length} ที่พัก · ไม่รวมประกาศซ้ำ</h3><p>ระยะเดินที่ยืนยันแล้ว ${data.properties.filter(p=>p.walkingVerified).length} แห่ง · ยืนยันกับเจ้าของ ${data.properties.filter(p=>p.ownerConfirmed).length} แห่ง</p></div></div><div class="update-content"><section class="panel"><h2>บันทึกการเปลี่ยนแปลง</h2>${data.changes?.length?data.changes.slice(0,30).map(c=>`<div class="change"><small>${new Date(c.at).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})}</small><h3>${esc(get(c.propertyId)?.name||c.propertyId)}</h3><p>${esc(c.summary)}</p></div>`).join(''):'<p>ยังไม่มีการเปลี่ยนแปลงที่บันทึกจากการตรวจอัตโนมัติครั้งก่อน</p>'}</section>${data.reviewQueue?.length?`<section class="panel"><h2>เบาะแสใหม่รอตรวจ ${data.reviewQueue.length} รายการ</h2><p>พบจากหน้ารวม แต่ยังไม่รับรองราคาเช่าสั้น ระยะเดิน หรือห้องว่าง</p>${data.reviewQueue.slice(0,30).map(c=>`<p><a class="source-link" href="${esc(safeUrl(c.url))}" target="_blank" rel="noopener noreferrer">${esc(c.name)} ↗</a> · ${esc(c.station)}</p>`).join('')}</section>`:''}<section class="panel"><h2>เราอ่านข้อมูลอย่างไร</h2><ul><li>อัปเดตราคาอัตโนมัติเฉพาะช่องสัญญา 1, 3 หรือ 6 เดือนที่ต้นทางแยกไว้ชัด ไม่ใช้ราคาคอลัมน์รายปีแทน</li><li>หากคำบรรยายหรือเงื่อนไขเปลี่ยน จะทำเครื่องหมาย “ต้องตรวจข้อมูลใหม่” เก็บข้อมูลเดิมไว้จนกว่าจะตรวจทาน</li><li>เว็บไซต์ล่ม หน้าเปลี่ยนรูปแบบ หรือมีหน้าล็อกอิน ไม่ถือว่าห้องเต็ม และไม่ลบข้อมูลเดิม</li><li>วันที่ตรวจหน้าเว็บไม่ใช่วันที่ผู้ประกาศแก้ไข และไม่ได้ยืนยันกับเจ้าของ</li><li>ตรวจประกาศที่เก็บไว้ และค้นเบาะแสจากหน้ารวม RentHub / Hongpak / ZmyHome ใน 7 สถานีเมื่ออนุญาตการเข้าถึงอัตโนมัติ โพสต์ Facebook อ่านด้วยตนเองจากสองกลุ่มสาธารณะ ไม่ได้ดึงใหม่ทุกชั่วโมง ไม่มีการเข้ากลุ่มปิดหรือส่งข้อความ</li><li>รูปจากต้นทางอาจแสดงไม่ได้เมื่อเจ้าของย้ายหรือลบรูป ระบบจะใช้ภาพระบุว่ายังไม่มีรูปแทน</li></ul></section></div></div>`;}

function sourcesPage(){
 const sourceCount=domain=>domain?data.properties.filter(p=>[p.sourceUrl,...(p.additionalSources||[]).map(v=>v.url)].some(u=>{try{return new URL(u).hostname.replace(/^www\./,"")===domain.replace(/^www\./,"");}catch{return false;}})).length:0;
 const monitored=sourceData.sources.filter(v=>v.mode!=='manual').length;
 const fullStation=sourceStation==='ศูนย์ฯ สิริกิติ์'?'ศูนย์การประชุมแห่งชาติสิริกิติ์':sourceStation;
 const queryFor=v=>'https://www.google.com/search?q='+encodeURIComponent((v.domain?'site:'+v.domain+' ':'')+'"MRT '+fullStation+'" ห้องเช่า รายเดือน สัญญาระยะสั้น');
 const queue=(data.reviewQueue||[]).filter(v=>!v.station||v.station===fullStation||v.station===sourceStation);
 app.innerHTML=`<div class="container section-page"><div class="eyebrow">MORE PLACES TO LOOK</div><h1>เปิดแหล่งค้นหาให้กว้างขึ้น.</h1><p class="source-intro">รวม ${sourceData.sources.length} แหล่งค้นหา พร้อมลิงก์ค้นตามสถานี แต่ละแหล่งมีขอบเขตการอ่านต่างกัน แค็ตตาล็อก ${data.properties.length} ที่พักรวมเบาะแสและรายการเต็ม จึงไม่ได้หมายความว่าทุกแห่งตรงเงื่อนไขหรือพร้อมเช่า</p>${data.researchSummary?`<section class="notice">การนำเข้า ${dt(data.researchSummary.checkedAt)}: ตรวจ ${num(data.researchSummary.detailPagesRead)} หน้าประกาศตรง · เพิ่ม ${num(data.researchSummary.newPropertyCount)} เบาะแสใหม่ · รวมหลักฐานกับที่พักเดิม ${num(data.researchSummary.mergedPropertyCount)} แห่ง · ยังต้องยืนยันสัญญาเช่าสั้นและทางเดิน</section>`:""}<div class="status-grid"><div class="panel"><small>แหล่งค้นหา</small><h3>${sourceData.sources.length} ช่องทาง</h3><p>แพลตฟอร์มประกาศ เพจสาธารณะ และเว็บไซต์เจ้าของ</p></div><div class="panel"><small>ตัวตรวจประกาศที่เก็บไว้</small><h3>${monitored} แหล่งรองรับ</h3><p>อ่านได้เฉพาะหน้าสาธารณะที่อนุญาต ไม่ได้ดึงทุกประกาศของแพลตฟอร์ม</p></div><div class="panel"><small>ตรวจระยะเดินจริง</small><h3>${data.properties.filter(p=>p.walkingVerified).length} แห่งยืนยันแล้ว</h3><p>ระยะหน้าเว็บและคำบรรยายยังแยกจากการตรวจเส้นทาง</p></div></div><div class="panel" style="margin-top:24px"><label class="filter-label" for="source-station">เลือกสถานีสำหรับเปิดค้นหา</label><select class="sort" id="source-station">${stations.map(st=>`<option ${st===sourceStation?'selected':''}>${st}</option>`).join('')}</select><p>ลิงก์ “ค้นประกาศสาธารณะ” เปิดผลค้นหาบนเว็บตามสถานีที่เลือก อาจยังมีผลนอกพื้นที่ ต้องตรวจที่ตั้งและสัญญาก่อนเพิ่มเป็นตัวเลือก</p></div>${data.facebookResearch?`<section class="panel" style="margin-top:24px"><h2>โพสต์จริงจาก Facebook 2 กลุ่ม</h2><p>นำเข้า ${facebookPosts().length} โพสต์ที่เปิดอ่านตรง พร้อมราคา สัญญา และเหตุผลที่แยกออก ไม่ใช่แค่ลิงก์กลุ่ม</p><a class="primary" href="#/facebook">ดูโพสต์ Facebook ↗</a><p>${esc(data.facebookResearch.automationNote)}</p></section>`:""}<div class="sources-grid">${sourceData.sources.map(v=>`<section class="panel source-card"><span class="source-state">${v.mode==='structured'?'ตรวจช่องราคาเช่าสั้นที่ระบุชัด':v.mode==='metadata'?'รองรับตรวจลิงก์ที่เก็บไว้':'แหล่งค้นเพิ่มเติม · ตรวจด้วยตนเอง'}</span><h2>${esc(v.name)}</h2><strong>${sourceCount(v.domain)} ที่พักมีประกาศนำเข้าจริง</strong><p>ตรวจแหล่งนี้ ${dt(v.searchedAt)} · ${(data.sourceAudit||[]).filter(a=>{try{return v.domain&&new URL(a.url).hostname.replace(/^www\./,"")===v.domain.replace(/^www\./,"");}catch{return false;}}).length} ประกาศมีผลตรวจแยกด้านล่าง</p><p>${esc(v.description)}</p><p>${esc(v.accessNote)}</p><div class="source-actions"><a class="primary" href="${esc(queryFor(v))}" target="_blank" rel="noopener noreferrer">ค้นประกาศสาธารณะ ↗</a>${v.url?`<a class="outline" href="${esc(safeUrl(v.url))}" target="_blank" rel="noopener noreferrer">เปิด ${esc(v.name)} ↗</a>`:''}</div></section>`).join('')}</div><section class="panel" style="margin-top:24px"><h2>เบาะแสจากหน้ารวม ${esc(sourceStation)} · ${queue.length} รายการ</h2><p>ยังไม่ใช่ห้องที่ผ่านเกณฑ์ ระยะสัญญา ราคาเช่าสั้น ที่ตั้งจริง และทางเดินต้องตรวจจากหน้าประกาศตรงก่อน รายการที่เป็นอาคารเดียวกับแค็ตตาล็อกจะถูกรวมในรอบตรวจทาน</p>${queue.length?queue.slice(0,100).map(v=>`<div class="queue-item"><a class="source-link" href="${esc(safeUrl(v.url))}" target="_blank" rel="noopener noreferrer">${esc(v.name)} ↗</a><div class="queue-meta">${esc(v.source||'RentHub')} · พบจากหน้ารวม ${esc(v.station||'ไม่ระบุ')} · ${v.websiteMeters!=null?'เว็บแสดง '+num(v.websiteMeters)+' ม.; ยังไม่ยืนยันระยะเดิน':'ยังไม่ยืนยันระยะเดิน'} · พบครั้งแรก ${dt(v.discoveredAt)}</div></div>`).join(''):'<p>ยังไม่มีเบาะแสเพิ่มเติมในคิวของสถานีนี้ เปิดแหล่งค้นด้านบนได้เลย</p>'}</section>${data.sourceAudit?.length?`<section class="panel" style="margin-top:24px"><h2>ผลตรวจประกาศตรงและรายการที่คัดออก</h2>${data.sourceAudit.map(v=>`<p><a class="source-link" href="${esc(safeUrl(v.url))}" target="_blank" rel="noopener noreferrer">${esc(v.source)} ↗</a> · ${esc(v.reason)}</p>`).join("")}</section>`:""}<section class="notice">ⓘ ไม่มีการส่งข้อความหาเจ้าของ อ่านสองกลุ่ม Facebook สาธารณะหลังได้รับอนุญาตเข้าสู่ระบบ ไม่มีการคัดลอกข้อมูลจากกลุ่มปิด และไม่ถือว่าค่าจากหน้าเว็บเป็นระยะเดินจริง</section></div>`;
}


function facebookPosts(){return data.properties.filter(p=>p.facebookGroupId);}
function facebookPage(){
 document.title='โพสต์ Facebook · NEAR ONE';
 const research=data.facebookResearch;
 const posts=facebookPosts();
 app.innerHTML=`<div class="container section-page"><div class="eyebrow">PUBLIC GROUP POSTS</div><h1>โพสต์จากสองกลุ่ม Facebook.</h1><p class="source-intro">${posts.length} โพสต์ที่อ่านต้นทางและนำเข้าแล้ว · แยกห้องว่างในอนาคต รายการเกินงบ และระยะเดินที่ยังไม่ผ่านเกณฑ์อย่างชัดเจน</p><div class="notice"><span>${esc(research?.automationNote||'ยังไม่ได้ตั้งระบบดึง Facebook อัตโนมัติ')}<br>ยังไม่มีห้องจากรอบนี้ที่ยืนยันครบทั้งราคาเช่าสั้น ระยะเดินถึงทางเข้า MRT และห้องว่างปัจจุบัน</span></div><div class="facebook-groups">${(research?.groups||[]).map(g=>`<section class="panel"><span class="source-state">ตรวจแล้ว · กลุ่มสาธารณะ</span><h2>${esc(g.name)}</h2><p>${posts.filter(p=>p.facebookGroupId===g.id).length} โพสต์นำเข้าจริง · ตรวจ ${dt(research.checkedAt)}</p><a class="outline" href="${esc(safeUrl(g.url))}" target="_blank" rel="noopener noreferrer">เปิดกลุ่มต้นทาง ↗</a></section>`).join('')}</div><div class="panel facebook-controls"><div><label class="filter-label" for="facebook-budget">ราคาเช่า / ราคาอ้างอิง ไม่เกิน ฿<span id="facebook-budget-value">${num(facebookState.budget)}</span></label><input class="range" id="facebook-budget" type="range" min="2500" max="30000" step="500" value="${facebookState.budget}"><p class="filter-note">ใช้ราคาอ้างอิงด้วยเมื่อยังไม่มีราคาเช่าสั้น การปรับงบไม่เปลี่ยนสถานะสัญญาหรือผลตรวจ</p></div><select class="sort" id="facebook-sort" aria-label="เรียงโพสต์ Facebook"><option value="asc" ${facebookState.sort==='asc'?'selected':''}>ราคา: น้อย → มาก</option><option value="desc" ${facebookState.sort==='desc'?'selected':''}>ราคา: มาก → น้อย</option></select><button class="outline" data-facebook-all>ดูทุกโพสต์ที่ตรวจ</button></div><h2>ผลตรวจโพสต์ <span id="facebook-count"></span></h2><p class="filter-note">รวมข้อมูลที่แยกออกเพื่อให้ตรวจสอบย้อนกลับได้ ไม่ใช่รายการแนะนำที่ผ่านเงื่อนไขทั้งหมด</p><div class="cards" id="facebook-results"></div><p>${esc(research?.scopeNote||'')}</p><a class="outline" href="#/">กลับไปกรองที่พักทั้งหมด ↗</a></div>`;
 renderFacebook();
}
function renderFacebook(){
 const posts=facebookPosts().filter(p=>{const n=filterPriceFor(p);return n===null||n<=facebookState.budget;}).sort((a,b)=>{const x=filterPriceFor(a),y=filterPriceFor(b);return x===null?y===null?0:1:y===null?-1:facebookState.sort==='asc'?x-y:y-x;});
 document.querySelector('#facebook-count').textContent=`${posts.length} จาก ${facebookPosts().length} โพสต์`;
 document.querySelector('#facebook-results').innerHTML=posts.length?posts.map(p=>card(p,'all')).join(''):'<div class="empty"><h3>ไม่มีโพสต์ในงบนี้</h3><p>ลองปรับงบหรือดูทุกโพสต์ที่ตรวจ</p></div>';
}

function notFound(){app.innerHTML='<div class="container section-page empty"><h1>ไม่พบหน้าที่ต้องการ</h1><a class="primary" href="#/">กลับไปค้นหาที่พัก</a></div>';}
function route(){const path=location.hash.slice(1)||'/';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===(location.hash||'#/')));if(path.startsWith('/stay/'))detail(get(decodeURIComponent(path.split('/')[2])));else if(path==='/favorites')favoritePage();else if(path==='/compare')comparePage();else if(path==='/updates')updates();else if(path==='/sources')sourcesPage();else if(path==='/facebook')facebookPage();else if(path==='/')home();else notFound();counts();}
app.addEventListener('click',e=>{if(e.target.closest('[data-facebook-all]')){facebookState.budget=30000;facebookPage();return;}const f=e.target.closest('[data-fav]');if(f){const id=f.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persist();toast(favorites.includes(id)?'บันทึกไว้ในรายการโปรดแล้ว':'นำออกจากรายการโปรดแล้ว');route();return;}const c=e.target.closest('button[data-compare]');if(c){toggleCompare(c.dataset.compare);route();return;}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;home();return;}const station=e.target.closest('[data-station]');if(station){state.station=station.dataset.station;home();return;}if(e.target.closest('[data-reset]')){state={budget:10000,query:'',tab:'all',station:'',sort:'recommended',term:'all',kinds:[],privateOnly:false,onlyKnown:false,walk:'all'};home();}if(e.target.closest('[data-expand]')){const expanded=document.querySelector('.filters')?.classList.toggle('expanded');e.target.closest('[data-expand]').setAttribute('aria-expanded',String(expanded));}});
function toggleCompare(id){if(!compare.includes(id)&&compare.length>=3){toast('เปรียบเทียบได้สูงสุด 3 ที่พัก กรุณานำรายการเดิมออกก่อน');return;}compare=compareSet(compare,id);persist();toast(compare.includes(id)?'เพิ่มในรายการเปรียบเทียบแล้ว':'นำออกจากรายการเปรียบเทียบแล้ว');}
app.addEventListener('change',e=>{if(e.target.id==='facebook-sort'){facebookState.sort=e.target.value;renderFacebook();return;}if(e.target.id==='source-station'){sourceStation=e.target.value;sourcesPage();return;}if(e.target.matches('[data-compare]')){toggleCompare(e.target.dataset.compare);e.target.checked=compare.includes(e.target.dataset.compare);}if(e.target.dataset.filter){state[e.target.dataset.filter]=e.target.checked;renderResults();}if(e.target.dataset.kind){state.kinds=e.target.checked?[...state.kinds,e.target.dataset.kind]:state.kinds.filter(k=>k!==e.target.dataset.kind);renderResults();}if(['term','sort','walk'].includes(e.target.id)){state[e.target.id]=e.target.value;renderResults();}});
app.addEventListener('input',e=>{if(e.target.id==='facebook-budget'){facebookState.budget=+e.target.value;document.querySelector('#facebook-budget-value').textContent=num(facebookState.budget);renderFacebook();return;}if(e.target.id==='budget'){state.budget=+e.target.value;document.querySelector('#budget-value').textContent=num(state.budget);renderResults();}if(e.target.id==='search'){state.query=e.target.value;renderResults();}});app.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();state.query=document.querySelector('#search').value;renderResults();document.querySelector('.browse').scrollIntoView({behavior:'smooth',block:'start'});}});
app.addEventListener('error',e=>{if(e.target.matches?.('img[data-fallback]')){e.target.removeAttribute('data-fallback');e.target.src='./assets/room-placeholder.svg';}},true);
window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0);});
async function load(){try{const r=await fetch('./data/listings.json',{cache:'no-cache'});if(!r.ok)throw Error();data=await r.json();try{const sr=await fetch('./data/sources.json');if(sr.ok)sourceData=await sr.json();}catch{}favorites=favorites.filter(id=>get(id));compare=compare.filter(id=>get(id));route();}catch{app.innerHTML='<div class="empty"><h2>โหลดข้อมูลไม่สำเร็จ</h2><p>กรุณาเปิดเว็บผ่านตัวเริ่มเซิร์ฟเวอร์ในโปรเจกต์ หรือรีเฟรชหน้าอีกครั้ง</p><button class="outline" id="retry">ลองอีกครั้ง</button></div>';document.querySelector('#retry').onclick=load;}}
load();setInterval(async()=>{try{const r=await fetch('./data/listings.json',{cache:'no-cache'});if(r.ok){data=await r.json();if(location.hash==='#/updates')updates();}}catch{}},300000);
